// MT2009_PLUS_GUILD_TREASURY_V1 (guild.cpp spend): pays iGold of the guild's
// land or buildings out of the treasury. False when the treasury lacks it.
bool CGuild::SpendGuildMoney(LPCHARACTER ch, YANG iGold, const char* c_pszWhat)
{
	if (iGold <= 0)
		return true;
	if (GetGuildMoneyAvailable() < iGold)
		return false;
	m_llMt2009SpendPending += iGold;

	TPacketGDGuildMoney p;
	p.dwGuild = GetID();
	p.iGold = iGold;
	db_clientdesc->DBPacket(HEADER_GD_GUILD_WITHDRAW_MONEY, 0, &p, sizeof(p));

	char buf[96 + 1];
	snprintf(buf, sizeof(buf), "%u %s %s", GetID(), GetName(), c_pszWhat ? c_pszWhat : "");
	if (ch)
		LogManager::instance().CharLog(ch, iGold, "GUILD_TREASURY_SPEND", buf);
	sys_log(0, "GUILD: TREASURY SPEND %s:%u gold %lld for %s", GetName(), GetID(), iGold, c_pszWhat ? c_pszWhat : "?");
	return true;
}

