	void			Mt2009DumpSent(const char* c_pszWhy);
protected:
	struct TMt2009Sent { DWORD dwTime; int iSize; BYTE bHeader; BYTE bSub; char szText[48]; };
	enum { MT2009_SENT_TRACE = 48 };
	TMt2009Sent		m_aMt2009Sent[MT2009_SENT_TRACE] = {};
	unsigned int	m_uMt2009SentNext = 0;

