new:
// MT2009_PLUS_PACKET_TRACE_V1 (desc.cpp): one line of the connection's trace -
// the header, the size, for a chat line its type and the start of its text
// (the bots' chat commands travel there); and anything over 16 KB goes to
// syserr at once with the receiver. A call is not always a whole packet - a
// dynamic packet's body often follows its header in a second call (the
// offline shops' entries) - so the first byte is only the header's guess and
// no size field is judged here.
void DESC::Mt2009NoteSent(const void* c_pvData, int iSize)
{
	if (!c_pvData || iSize <= 0)
		return;
	const BYTE* p = static_cast<const BYTE*>(c_pvData);
	TMt2009Sent& s = m_aMt2009Sent[m_uMt2009SentNext++ % MT2009_SENT_TRACE];
	s.dwTime = get_dword_time();
	s.iSize = iSize;
	s.bHeader = p[0];
	s.bSub = 0;
	s.szText[0] = '\0';
	const char* who = GetCharacter() ? GetCharacter()->GetName() : GetHostName();
	if (p[0] == HEADER_GC_CHAT && iSize >= (int)sizeof(TPacketGCChat))
	{
		const TPacketGCChat* chat = reinterpret_cast<const TPacketGCChat*>(p);
		s.bSub = chat->type;
		const int textLen = MIN((int)sizeof(s.szText) - 1, iSize - (int)sizeof(TPacketGCChat));
		for (int i = 0; i < textLen; ++i)
		{
			const BYTE c = p[sizeof(TPacketGCChat) + i];
			s.szText[i] = (c < 32 || c == 127) ? '.' : (char)c;
		}
		s.szText[MAX(0, textLen)] = '\0';
	}
	if (iSize > 16384)
		sys_err("PACKET_TRACE: big packet header %u size %d to %s", (unsigned int)p[0], iSize, who);
}

void DESC::Mt2009DumpSent(const char* c_pszWhy)
{
	const DWORD now = get_dword_time();
	sys_err("PACKET_TRACE: %s - %s (%s) phase %d, the last packets sent to it, oldest first:",
			c_pszWhy ? c_pszWhy : "?", GetCharacter() ? GetCharacter()->GetName() : "-", GetHostName(), m_iPhase);
	const unsigned int count = MIN((unsigned int)MT2009_SENT_TRACE, m_uMt2009SentNext);
	for (unsigned int k = 0; k < count; ++k)
	{
		const TMt2009Sent& s = m_aMt2009Sent[(m_uMt2009SentNext - count + k) % MT2009_SENT_TRACE];
		if (s.bHeader == HEADER_GC_CHAT)
			sys_err("PACKET_TRACE:   -%ums header %u size %d chat type %u '%s'", now - s.dwTime,
					(unsigned int)s.bHeader, s.iSize, (unsigned int)s.bSub, s.szText);
		else
			sys_err("PACKET_TRACE:   -%ums header %u size %d", now - s.dwTime, (unsigned int)s.bHeader, s.iSize);
	}
}

